// Flash memory start id
uint8_t SensorBME680::sMagicWord[] = {0xCA, 0xFE, 0x3D, 0x76};

uint8_t SensorBME680::getSensorClass()
{
    return SENS_BME680;
}

std::string SensorBME680::logPrefix()
{
    return "Sensor<BME680>";
}

void SensorBME680::delayCallback(bme68x_delay_us_fptr_t iDelayCallback)
{
    mDelayCallback = iDelayCallback;
}

void SensorBME680::delayCallbackActive(bool iOn)
{
    mDelayCallbackIsActive = iOn;
}

void SensorBME680::setMagicKeyOffset(uint8_t iMagicKeyOffset)
{
    sMagicWord[0] ^= iMagicKeyOffset;
}

/*!
 * @brief implements a state engine to restart the sensor without delays
 */
void SensorBME680::sensorLoopInternal()
{
    bool lResult = false;
    if (mDelayCallbackIsActive)
        return;
    switch (pSensorState)
    {
        case Wakeup:
        // if (delayCheck(pSensorStateDelay, 60000))
        if (pSensorStateDelay == 0 || delayCheck(pSensorStateDelay, 1000))
            {
                Sensor::sensorLoopInternal();
            }
            break;
        case Calibrate:
            if (delayCheck(pSensorStateDelay, 100))
            {
                sensorLoadState();
                lResult = checkIaqSensorStatus();
                pSensorState = lResult ? Finalize : Off;
                pSensorStateDelay = millis();
                if (lResult)
                    Bsec2::run();
                logResult(lResult);
            }
            break;
        case Finalize:
            if (delayCheck(pSensorStateDelay, 3000))
            {
                // as long as there are no new values, sensor is not yet ready
                if (Bsec2::run()) pSensorState = Running;
                pSensorStateDelay = millis();
            }
            break;
        case Running:
            if (delayCheck(pSensorStateDelay, 3000)) {
                if (Bsec2::run())
                {
                    if (Bsec2::status != 100) checkIaqSensorStatus();
                }
                pSensorStateDelay = millis();
            }
            break;
        default:
            pSensorStateDelay = millis();
            break;
    }
}

float SensorBME680::measureValue(MeasureType iMeasureType)
{
    switch (iMeasureType)
    {
        case Temperature:
            return temperature;
            break;
        case Humidity:
            return humidity;
            break;
        case Pressure:
            return pressure;
            break;
        case Voc:
            return iaq;
            break;
        case Co2Calc:
            return co2Equivalent;
            break;
        case Accuracy:
            return (iaqAccuracy / 3.0f) * 100.0f;
            break;
        default:
            break;
    }
    return NO_NUM;
}

bool SensorBME680::begin()
{
    logInfoP("Starting sensor BME680... ");
    bool lResult = false;
    if (pI2CAddress == 0)
    {
        logInfoP("Determine I2C address of BME680... ");
        pI2CAddress = BME680_I2C_ADDR_PRIMARY;
        lResult = Sensor::begin();
        if (!lResult)
        {
            pI2CAddress = BME680_I2C_ADDR_SECONDARY;
            lResult = Sensor::begin();
        }
    } else {
        lResult = Sensor::begin();
    }
    if (lResult)
    {
        logInfoP("Found BME680 at address 0x%02X", pI2CAddress);
        Bsec2::begin(pI2CAddress, *pWire, mDelayCallback);
        lResult = checkIaqSensorStatus();
    }
    if (lResult) lResult = reinitialize();
    logResult(lResult);
    return lResult;
}

bool SensorBME680::reinitialize()
{
    bool lResult = false;
    Bsec2::setConfig(bsec_config_iaq);
    lResult = checkIaqSensorStatus();
    if (lResult)
    {
        Bsec2::updateSubscription(sensorList, sizeof(sensorList), BSEC_SAMPLE_RATE_LP);
        lResult = checkIaqSensorStatus();
    }
    if (lResult) {
        Bsec2::setTemperatureOffset(-pTempOffset);
        attachCallback(bme680DataCallback);
    }
    return lResult;
}

uint8_t SensorBME680::getI2cSpeed()
{
    return 4; // n * 100kHz
}

void SensorBME680::bme680DataCallback(const bme68xData data, const bsecOutputs outputs, Bsec2 bsec)
{
    if (!outputs.nOutputs)
    {
        return;
    }

    // Serial.println("BSEC outputs:\n\tTime stamp = " + String((int) (outputs.output[0].time_stamp / INT64_C(1000000))));
    for (uint8_t i = 0; i < outputs.nOutputs; i++)
    {
        const bsecData output  = outputs.output[i];
        switch (output.sensor_id)
        {
            case BSEC_OUTPUT_IAQ:
                SensorBME680::iaq = output.signal;
                SensorBME680::iaqAccuracy = output.accuracy;
                break;
            // case BSEC_OUTPUT_RAW_TEMPERATURE:
            //     temperature = output.signal;
            //     break;
            case BSEC_OUTPUT_RAW_PRESSURE:
                SensorBME680::pressure = output.signal * 100.0; // pressure seems to be in hPa, not in Pa
                break;
            // case BSEC_OUTPUT_RAW_HUMIDITY:
            //     humidity = output.signal;
            //     break;
            case BSEC_OUTPUT_SENSOR_HEAT_COMPENSATED_TEMPERATURE:
                SensorBME680::temperature = output.signal;
                break;
            case BSEC_OUTPUT_SENSOR_HEAT_COMPENSATED_HUMIDITY:
                SensorBME680::humidity = output.signal;
                break;
            case BSEC_OUTPUT_CO2_EQUIVALENT:
                SensorBME680::co2Equivalent = output.signal;
            default:
                break;
        }
    }
}


bool SensorBME680::checkIaqSensorStatus(void)
{
    if (Bsec2::status < BSEC_OK)
    {
        logDebugP("BSEC error code : %d", Bsec2::status);
        return false;
        // fatalError(-iaqSensor.status, "BSEC error code");
    }
    else if (Bsec2::status > BSEC_OK)
        logDebugP("BSEC warning code : %d", Bsec2::status);

    if (Bsec2::sensor.status < BME680_OK)
    {
        // logDebugP("BME680 error code : %d", Bsec2::sensor.status);
        return false;
        // fatalError(-iaqSensor.bme680Status, "BME680 error code");
    }
    // else if (Bsec2::sensor.status > BME680_OK && Bsec2::sensor.status != 100) // 100 is BME680 warning code for "no new data"
    else if (Bsec2::sensor.status > BME680_OK)
        logDebugP("BME680 warning code : %d", Bsec2::sensor.status);

    return true;
}

void SensorBME680::sensorLoadState()
{
    if (mFlashBuffer)
    {
        Bsec2::setState((uint8_t*)mFlashBuffer);
        bool lResult = checkIaqSensorStatus();
        if (lResult)
        {
            logDebugP("BME680 was successfully calibrated from Flash");
        }
        else
        {
            logDebugP("*** BME680 calibration from Flash failed! ***");
            reinitialize();
        }
    }
    else
    {
        logDebugP("BME680 calibration data in Flash has wrong ID and will be deleted!");
    }
}

