// IFlashUserData
void SensorBME680::sensorReadFlash(const uint8_t* iBuffer, const uint16_t iSize)
{
    bool lValid = (iBuffer[0] == 1); // check version first
    logDebugP("Reading state from Flash");
    // read magic word
    for (uint8_t i = 1; i < 5 && lValid; i++)
    {
        // logDebugP("%02X ", iBuffer[i]);
        lValid = lValid && (iBuffer[i] == sMagicWord[i - 1]);
    }

    mFlashBuffer = lValid ? iBuffer + 5 : nullptr;

    logIndentUp();
    if (!lValid)
        logDebugP("No valid data in Flash");
    else
    {
        logDebugP("Calibration data read from flash");
        // we read here just to use the byte stream, data itself is contained in mFlashBuffer
        openknx.flash.read(sensorFlashSize() - 1);
        // for (uint8_t i = 1; i < sensorFlashSize(); i++)
        //     openknx.flash.readByte();
    }
    logIndentDown();
}

void SensorBME680::sensorSavePower()
{
    Bsec2::getState(mWorkBuffer);
    mWorkBufferInitialized = true;
}

void SensorBME680::sensorWriteFlash()
{
    if (!mWorkBufferInitialized) sensorSavePower();
    openknx.flash.writeByte(1); // version
    for (uint8_t lIndex = 0; lIndex < 4; lIndex++)
        openknx.flash.writeByte(sMagicWord[lIndex]);
    openknx.flash.write(mWorkBuffer, BME680_SAVE_SIZE - 6);
    bool lCheck = checkIaqSensorStatus();
    if (lCheck)
    {
        logDebugP("BME680: Written state to Flash\n");
    }
    mWorkBufferInitialized = false;
}

uint16_t SensorBME680::sensorFlashSize()
{
    return BME680_SAVE_SIZE;
}

